_SESSION_KEYS = {"logged_in", "phone", "name", "user_name"}


def _value_at(payload: Any, path: str) -> Any:
    value = payload
    for part in path.split("."):
        if not isinstance(value, Mapping):
            return None
        value = value.get(part)
    return value


def _equal(actual: Any, expected: Any) -> bool:
    if isinstance(expected, bool):
        return bool(actual) is expected
    if isinstance(expected, (int, float)):
        try:
            return float(actual) == float(expected)
        except (TypeError, ValueError):
            return False
    return str(actual) == str(expected)


class _OpenTripStateEvaluator(BaseEvaluator):
    """Shared reading of the OpenTrip document and of the declared outcome."""

    #: when true, a task whose every check is absent still fails
    REQUIRE_BOOKINGS = True

    def read_state(self, context: Mapping[str, Any]) -> tuple[dict[str, Any], str]:
        params = dict(context.get("params") or {})
        timeout = int(params.get("timeout", 20) or 20)
        try:
            payload = read_opentrip_local_state(
                context.get("controller"),
                timeout=timeout,
                leveldb_path=str(params.get("leveldb_path") or DEFAULT_LEVELDB_PATH),
            )
            return dict(payload["state"]), "stored"
        except RuntimeError:
            payload = read_opentrip_seed_baseline(
                context.get("controller"),
                timeout=timeout,
                seed_data_path=str(params.get("seed_data_path") or DEFAULT_SEED_DATA_PATH),
            )
            return dict(payload["state"]), "seed"

    @staticmethod
    def session_result(state: Mapping[str, Any], expected: Mapping[str, Any]) -> tuple[bool, dict[str, Any]]:
        session = state.get("session") if isinstance(state.get("session"), Mapping) else {}
        user = session.get("user") if isinstance(session.get("user"), Mapping) else {}
        observed = {"logged_in": bool(session.get("loggedIn")), "phone": user.get("phone"), "name": user.get("name")}
        passed = observed["logged_in"] == bool(expected.get("logged_in", True))
        for key in ("phone", "name", "user_name"):
            if key in expected and expected.get(key) is not None:
                field = "name" if key == "user_name" else key
                if str(observed.get(field) or "") != str(expected.get(key) or ""):
                    passed = False
        return passed, observed

    @staticmethod
    def match_booking(
        expected: Mapping[str, Any],
        bookings: list[dict[str, Any]],
        baseline_ids: list[str] | None = None,
    ) -> dict[str, Any]:
        baseline = set(baseline_ids or [])
        candidates = list(bookings)
        if expected.get("type") is not None:
            candidates = [row for row in candidates if _equal(row.get("type"), expected["type"])]
        if expected.get("note") is not None:
            candidates = [row for row in candidates if _equal(row.get("note"), expected["note"])]
        if expected.get("item_id") is not None:
            candidates = [row for row in candidates if _equal(_value_at(row, "item.id"), expected["item_id"])]
        if expected.get("hotel_name") is not None:
            candidates = [row for row in candidates if _equal(_value_at(row, "item.name"), expected["hotel_name"])]
        matched = [row for row in candidates if all(
            _equal(_value_at(row, path), expected[key])
            for key, path in FIELD_PATHS.items()
            if key in expected and key not in ("type", "note", "item_id", "hotel_name")
        )]
        if expected.get("id_prefix") is not None:
            matched = [row for row in matched if str(row.get("id") or "").startswith(str(expected["id_prefix"]))]
        if not expected.get("allow_baseline_id"):
            matched = [row for row in matched if str(row.get("id") or "") not in baseline]
        created_after = str(expected.get("created_after") or "")
        if created_after:
            kept = []
            for row in matched:
                try:
                    actual = datetime.fromisoformat(str(row.get("createdAt") or "").replace("Z", "+00:00"))
                    cutoff = datetime.fromisoformat(created_after.replace("Z", "+00:00"))
                except ValueError:
                    continue
                if actual > cutoff:
                    kept.append(row)
            matched = kept
        return {
            "matched": len(matched) == 1,
            "candidate_count": len(candidates),
            "match_count": len(matched),
            "booking_id": str(matched[0].get("id") or "") if len(matched) == 1 else None,
            "actual": compact_booking(matched[0]) if len(matched) == 1 else None,
        }

    def verdict(
        self,
        checks: list[dict[str, Any]],
        failures: list[str],
        metadata: dict[str, Any],
    ) -> EvalResult:
        metadata = dict(metadata)
        metadata["checks"] = checks
        metadata["failures"] = failures
        metadata["read_only"] = True
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenTrip final state does not satisfy the task: " + "; ".join(failures[:6]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message="OpenTrip final state verified", metadata=metadata)

    @staticmethod
    def add(
        checks: list[dict[str, Any]],
        failures: list[str],
        name: str,
        passed: bool,
        expected: Any = None,
        observed: Any = None,
        reason: str = "",
    ) -> None:
        record: dict[str, Any] = {"name": name, "passed": bool(passed), "expected": expected, "observed": observed}
        if not passed:
            record["failure_reason"] = reason
            failures.append(f"{name}: {reason}")
        checks.append(record)


class OpenTripApiEvaluator(_OpenTripStateEvaluator):
    """Verify the booking outcome a task declares for the travel workflow."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        checks: list[dict[str, Any]] = []
        failures: list[str] = []
        state, origin = self.read_state(context)
        bookings = [dict(row) for row in (state.get("bookings") or []) if isinstance(row, Mapping)]

        expected_session = dict(params.get("session") or {})
        if expected_session:
            passed, observed = self.session_result(state, expected_session)
            self.add(checks, failures, "session", passed, expected_session, observed,
                     "the signed-in account is not the declared one")

        declared = params.get("bookings") or {}
        items: list[dict[str, Any]] = []
        expected_count = None
        if isinstance(declared, Mapping):
            if declared.get("latest"):
                items = [dict(declared["latest"])]
            if declared.get("items"):
                items = [dict(row) for row in declared["items"] if isinstance(row, Mapping)]
            if declared.get("count") is not None:
                expected_count = int(declared["count"])
        elif isinstance(declared, list):
            items = [dict(row) for row in declared if isinstance(row, Mapping)]
        if params.get("required_bookings"):
            items = [dict(row) for row in params["required_bookings"] if isinstance(row, Mapping)]

        baseline_ids = [str(item) for item in params.get("baseline_booking_ids") or []]
        if expected_count is not None:
            self.add(checks, failures, "booking_count", len(bookings) == expected_count,
                     expected_count, len(bookings),
                     "the stored booking count is not the declared one")

        for expected in items:
            result = self.match_booking(expected, bookings, baseline_ids)
            self.add(
                checks, failures,
                f"booking:{expected.get('label') or expected.get('note') or expected.get('hotel_name') or expected.get('flight_no')}",
                result["matched"], expected, result,
                "no single stored booking satisfies the declared fields",
            )

        metadata = {
            "state_origin": origin,
            "session_actual": dict(state.get("session") or {}),
            "booking_count_actual": len(bookings),
            "bookings_actual": [compact_booking(row) for row in bookings],
        }
        return self.verdict(checks, failures, metadata)


class OpenTripBookingEvaluator(_OpenTripStateEvaluator):
    """Verify exact, attributable booking state without changing the guest."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        checks: list[dict[str, Any]] = []
        failures: list[str] = []
        state, origin = self.read_state(context)
        bookings = [dict(row) for row in (state.get("bookings") or []) if isinstance(row, Mapping)]
        baseline_ids = self._baseline_ids(context.get("run_dir"), params)

        expected_session = dict(params.get("session") or {})
        if expected_session:
            passed, observed = self.session_result(state, expected_session)
            self.add(checks, failures, "session", passed, expected_session, observed,
                     "the signed-in account is not the declared one")

        expected_count = int(params.get("expected_total_booking_count",
                                        len(baseline_ids) + len(params.get("required_bookings") or [])))
        self.add(checks, failures, "booking_count", len(bookings) == expected_count,
                 expected_count, len(bookings),
                 "unexpected booking count; a booking is missing, duplicated or unrelated")

        actual_ids = [str(row.get("id") or "") for row in bookings]
        self.add(checks, failures, "baseline_ids_preserved", set(baseline_ids).issubset(set(actual_ids)),
                 baseline_ids, actual_ids, "one or more bookings present at the start are gone")

        matched_ids: list[str] = []
        for expected in params.get("required_bookings") or []:
            expected = dict(expected)
            result = self.match_booking(expected, bookings, baseline_ids)
            self.add(
                checks, failures,
                f"booking:{expected.get('label') or expected.get('note')}",
                result["matched"], expected, result,
                "no single new booking satisfies the declared fields",
            )
            if result["matched"]:
                matched_ids.append(str(result.get("booking_id") or ""))

        self.add(checks, failures, "distinct_new_booking_ids",
                 len(matched_ids) == len(set(matched_ids)) == len(params.get("required_bookings") or []),
                 len(params.get("required_bookings") or []), matched_ids,
                 "the required bookings did not resolve to distinct new records")

        ui = self._ui_evidence(context.get("final_observation"), list(params.get("final_ui_contains") or []))
        if ui["applicable"]:
            self.add(checks, failures, "final_profile_ui", ui["passed"],
                     ui["required_tokens"], ui, "the final view is not the required OpenTrip page")

        metadata = {
            "state_origin": origin,
            "baseline_booking_ids": baseline_ids,
            "matched_object_ids": matched_ids,
            "booking_count_actual": len(bookings),
            "bookings_actual": [compact_booking(row) for row in bookings],
            "ui_evidence": ui,
        }
        return self.verdict(checks, failures, metadata)

    @staticmethod
    def _baseline_ids(run_dir: Any, params: Mapping[str, Any]) -> list[str]:
        configured = [str(item) for item in (params.get("baseline_booking_ids") or [])]
        if not run_dir:
            return configured
        path = Path(run_dir) / "opentrip_baseline.json"
        if not path.is_file():
            return configured
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except ValueError:
            return configured
        observed = [str(item) for item in (payload.get("booking_ids") or [])]
        return observed or configured

    @staticmethod
    def _ui_evidence(observation: Any, required_tokens: list[str]) -> dict[str, Any]:
        nodes = [node for node in (getattr(observation, "ui_nodes", []) or []) if isinstance(node, Mapping)]
        foreground = str(getattr(observation, "foreground_app", "") or "")
        parts = [str(getattr(observation, "foreground_window", "") or ""), foreground]
        for node in nodes:
            parts.extend([str(node.get("text") or ""), str(node.get("selector") or "")])
        joined = "\n".join(part for part in parts if part)
        applicable = bool(required_tokens) and (bool(nodes) or bool(foreground))
        matches = {token: token in joined for token in required_tokens}
        return {
            "applicable": applicable,
            "passed": applicable and all(matches.values()),
            "required_tokens": required_tokens,
            "token_matches": matches,
            "foreground_app": foreground,
            "ui_node_count": len(nodes),
        }


class OpenTripDualBookingEvaluator(_OpenTripStateEvaluator):
    """Verify that a two-booking itinerary left the declared records behind."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        checks: list[dict[str, Any]] = []
        failures: list[str] = []
        state, origin = self.read_state(context)
        bookings = [dict(row) for row in (state.get("bookings") or []) if isinstance(row, Mapping)]

        expected_user = dict(params.get("expected_user") or {})
        if expected_user:
            passed, observed = self.session_result(state, {
                "logged_in": True,
                "name": expected_user.get("name"),
                "phone": expected_user.get("phone"),
            })
            self.add(checks, failures, "session", passed, expected_user, observed,
                     "the signed-in account is not the declared one")

        baseline_ids = [str(item) for item in params.get("baseline_booking_ids") or []]
        expected_total = params.get("expected_total_booking_count")
        if expected_total is not None:
            self.add(checks, failures, "booking_count", len(bookings) == int(expected_total),
                     int(expected_total), len(bookings),
                     "the stored booking count is not the declared one")

        new_ids = [str(row.get("id") or "") for row in bookings if str(row.get("id") or "") not in set(baseline_ids)]
        expected_new = params.get("expected_new_booking_count")
        if expected_new is not None:
            self.add(checks, failures, "new_booking_count", len(new_ids) == int(expected_new),
                     int(expected_new), len(new_ids),
                     "the number of bookings added by the task is not the declared one")

        for key in ("expected_flight", "expected_hotel"):
            expected = params.get(key)
            if not isinstance(expected, Mapping):
                continue
            result = self.match_booking(dict(expected), bookings, baseline_ids)
            self.add(checks, failures, f"booking:{key}", result["matched"], dict(expected), result,
                     "no single new booking satisfies the declared fields")

        metadata = {
            "state_origin": origin,
            "baseline_booking_ids": baseline_ids,
            "new_booking_ids": new_ids,
            "booking_count_actual": len(bookings),
            "bookings_actual": [compact_booking(row) for row in bookings],
        }
        return self.verdict(checks, failures, metadata)
